var NEW=[["custom", "Касание", "Африканская равнина · Вольер жирафов", "Два жирафа сошлись мордами у края вольера. Я не двигался, пока они не разошлись сами.", 0, "data:image/webp;base64,"], ["custom", "Дневной сон", "Скальный выступ · Вольер львов", "Лев спит на нагретом камне. Единственное, что здесь можно сделать правильно, — не разбудить.", 0, "data:image/webp;base64,"], ["custom", "Обед без спешки", "Павильон «Бамбуковая роща»", "Побег бамбука, папоротник и никакой спешки. Я ждал, пока она сама посмотрит в кадр.", 0, "data:image/webp;base64,"], ["custom", "Мокрый и счастливый", "Контактный двор · Большая лужайка", "Пёс выскочил из воды и стряхнул её прямо на бегу. Кадр существовал доли секунды.", 0, "data:image/webp;base64,"], ["custom", "Шляпа на лето", "Мини-зоопарк · Детский уголок", "Лепесток упал ей на голову, и она просто решила его оставить.", 0, "data:image/webp;base64,"], ["custom", "Не внесён в каталог", "Закрытая секция · Без номера вольера", "Этот вид пока не описан наукой. Ушей у него больше, чем свидетелей.", 0, "data:image/webp;base64,"]];
